import{_ as l,o as i,c as e,ag as t}from"./chunks/framework.i8sMDeRW.js";const u=JSON.parse('{"title":"第 6 课：开源模型 vs 闭源模型","description":"","frontmatter":{},"headers":[],"relativePath":"guide/12-llm-engineering/06-open-source-vs-closed-source.md","filePath":"guide/12-llm-engineering/06-open-source-vs-closed-source.md","lastUpdated":1782288443000}'),p={name:"guide/12-llm-engineering/06-open-source-vs-closed-source.md"};function n(s,a,r,o,h,d){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="第-6-课-开源模型-vs-闭源模型" tabindex="-1">第 6 课：开源模型 vs 闭源模型 <a class="header-anchor" href="#第-6-课-开源模型-vs-闭源模型" aria-label="Permalink to &quot;第 6 课：开源模型 vs 闭源模型&quot;">​</a></h1><blockquote><p>本课目标：理解开源模型和闭源模型的区别，知道什么时候应该用 API 模型，什么时候应该用本地或自托管模型，以及产品经理在选型时应该看哪些因素。</p></blockquote><hr><h2 id="_1-先说结论" tabindex="-1">1. 先说结论 <a class="header-anchor" href="#_1-先说结论" aria-label="Permalink to &quot;1. 先说结论&quot;">​</a></h2><p>LLM 大致可以分成两类：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>闭源模型：你通过 API 或产品使用，通常看不到模型权重</span></span>
<span class="line"><span>开源模型：你可以下载或自托管，通常能更自由地部署和改造</span></span></code></pre></div><p>注意，这里的“开源”在 AI 领域有时比较复杂。</p><p>有些模型开放权重，但不一定完全开放训练数据、训练代码或商业使用权。</p><p>所以更准确地说：</p><blockquote><p>选模型时，不要只看“开源”两个字，要看许可证、权重、部署方式、成本、能力和风险。</p></blockquote><hr><h2 id="_2-什么是闭源模型" tabindex="-1">2. 什么是闭源模型？ <a class="header-anchor" href="#_2-什么是闭源模型" aria-label="Permalink to &quot;2. 什么是闭源模型？&quot;">​</a></h2><p>闭源模型通常指：</p><blockquote><p>模型由某家公司训练和托管，你通过 API 或网页产品使用它，但看不到完整模型内部。</p></blockquote><p>常见例子包括：</p><ul><li>OpenAI 的模型</li><li>Anthropic Claude</li><li>Google Gemini</li><li>部分云厂商托管模型</li></ul><p>你通常使用方式是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的应用</span></span>
<span class="line"><span>→ 调用模型 API</span></span>
<span class="line"><span>→ 模型服务返回答案</span></span></code></pre></div><p>你不需要自己管理 GPU、模型文件、推理框架和扩缩容。</p><hr><h2 id="_3-什么是开源模型" tabindex="-1">3. 什么是开源模型？ <a class="header-anchor" href="#_3-什么是开源模型" aria-label="Permalink to &quot;3. 什么是开源模型？&quot;">​</a></h2><p>开源模型通常指：</p><blockquote><p>模型权重可以被下载、部署或进一步微调。</p></blockquote><p>常见例子包括：</p><ul><li>Llama 系列</li><li>Qwen 系列</li><li>Mistral 系列</li><li>DeepSeek 系列</li><li>Gemma 系列</li></ul><p>你可以把模型运行在：</p><ul><li>本地电脑</li><li>公司服务器</li><li>云 GPU</li><li>边缘设备</li><li>手机或笔记本上的轻量环境</li></ul><p>使用方式可能是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下载模型</span></span>
<span class="line"><span>→ 选择推理框架</span></span>
<span class="line"><span>→ 部署服务</span></span>
<span class="line"><span>→ 你的应用调用自己的模型服务</span></span></code></pre></div><hr><h2 id="_4-生活类比-外卖-vs-自建厨房" tabindex="-1">4. 生活类比：外卖 vs 自建厨房 <a class="header-anchor" href="#_4-生活类比-外卖-vs-自建厨房" aria-label="Permalink to &quot;4. 生活类比：外卖 vs 自建厨房&quot;">​</a></h2><p>闭源模型像点外卖。</p><p>优点：</p><ul><li>快</li><li>方便</li><li>不用买厨房设备</li><li>不用雇厨师</li><li>菜品质量通常稳定</li></ul><p>缺点：</p><ul><li>菜价由别人定</li><li>菜谱你不能改太多</li><li>高峰期可能排队</li><li>食材来源你不完全掌控</li></ul><p>开源模型像自建厨房。</p><p>优点：</p><ul><li>菜谱可控</li><li>成本结构可控</li><li>可以服务内部特殊需求</li><li>数据不一定要出公司</li><li>可以深度改造</li></ul><p>缺点：</p><ul><li>要买设备</li><li>要维护厨房</li><li>要懂运营</li><li>出问题要自己修</li><li>初期门槛更高</li></ul><p>一句话：</p><blockquote><p>闭源模型更像买服务，开源模型更像建能力。</p></blockquote><hr><h2 id="_5-闭源模型的优点" tabindex="-1">5. 闭源模型的优点 <a class="header-anchor" href="#_5-闭源模型的优点" aria-label="Permalink to &quot;5. 闭源模型的优点&quot;">​</a></h2><h3 id="优点-1-上手快" tabindex="-1">优点 1：上手快 <a class="header-anchor" href="#优点-1-上手快" aria-label="Permalink to &quot;优点 1：上手快&quot;">​</a></h3><p>你只需要申请 API key，然后调用接口。</p><p>不需要自己部署模型。</p><p>适合：</p><ul><li>快速 MVP</li><li>原型验证</li><li>小团队试错</li><li>功能上线早期</li></ul><h3 id="优点-2-综合能力强" tabindex="-1">优点 2：综合能力强 <a class="header-anchor" href="#优点-2-综合能力强" aria-label="Permalink to &quot;优点 2：综合能力强&quot;">​</a></h3><p>闭源大模型通常在通用任务上表现很好，例如：</p><ul><li>写作</li><li>总结</li><li>代码</li><li>多语言</li><li>推理</li><li>工具调用</li><li>多模态</li></ul><h3 id="优点-3-运维成本低" tabindex="-1">优点 3：运维成本低 <a class="header-anchor" href="#优点-3-运维成本低" aria-label="Permalink to &quot;优点 3：运维成本低&quot;">​</a></h3><p>你不用管：</p><ul><li>GPU 驱动</li><li>显存</li><li>推理框架</li><li>模型量化</li><li>服务扩缩容</li><li>高并发调度</li></ul><p>这些由模型服务商处理。</p><h3 id="优点-4-更新快" tabindex="-1">优点 4：更新快 <a class="header-anchor" href="#优点-4-更新快" aria-label="Permalink to &quot;优点 4：更新快&quot;">​</a></h3><p>模型服务商会持续升级模型。</p><p>你可以比较快用到新能力。</p><hr><h2 id="_6-闭源模型的缺点" tabindex="-1">6. 闭源模型的缺点 <a class="header-anchor" href="#_6-闭源模型的缺点" aria-label="Permalink to &quot;6. 闭源模型的缺点&quot;">​</a></h2><h3 id="缺点-1-成本可能不可控" tabindex="-1">缺点 1：成本可能不可控 <a class="header-anchor" href="#缺点-1-成本可能不可控" aria-label="Permalink to &quot;缺点 1：成本可能不可控&quot;">​</a></h3><p>API 通常按 token 计费。</p><p>如果用户量大、输入长、输出长，成本可能快速上升。</p><p>比如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>长文档分析</span></span>
<span class="line"><span>多轮对话</span></span>
<span class="line"><span>大量客服请求</span></span>
<span class="line"><span>批量内容生成</span></span></code></pre></div><p>都可能烧 token。</p><h3 id="缺点-2-数据和合规压力" tabindex="-1">缺点 2：数据和合规压力 <a class="header-anchor" href="#缺点-2-数据和合规压力" aria-label="Permalink to &quot;缺点 2：数据和合规压力&quot;">​</a></h3><p>如果业务涉及：</p><ul><li>医疗数据</li><li>金融数据</li><li>企业内部文档</li><li>用户隐私</li><li>代码仓库</li><li>政府或涉密数据</li></ul><p>就要认真评估数据是否可以发给第三方 API。</p><h3 id="缺点-3-可控性有限" tabindex="-1">缺点 3：可控性有限 <a class="header-anchor" href="#缺点-3-可控性有限" aria-label="Permalink to &quot;缺点 3：可控性有限&quot;">​</a></h3><p>你不能完全控制：</p><ul><li>模型权重</li><li>训练数据</li><li>内部推理细节</li><li>版本升级节奏</li><li>某些安全策略</li></ul><h3 id="缺点-4-供应商锁定" tabindex="-1">缺点 4：供应商锁定 <a class="header-anchor" href="#缺点-4-供应商锁定" aria-label="Permalink to &quot;缺点 4：供应商锁定&quot;">​</a></h3><p>如果你的系统深度依赖某个闭源模型特性，将来迁移可能困难。</p><p>例如：</p><ul><li>特定 function calling 格式</li><li>特定多模态输入方式</li><li>特定上下文长度</li><li>特定输出风格</li></ul><hr><h2 id="_7-开源模型的优点" tabindex="-1">7. 开源模型的优点 <a class="header-anchor" href="#_7-开源模型的优点" aria-label="Permalink to &quot;7. 开源模型的优点&quot;">​</a></h2><h3 id="优点-1-部署可控" tabindex="-1">优点 1：部署可控 <a class="header-anchor" href="#优点-1-部署可控" aria-label="Permalink to &quot;优点 1：部署可控&quot;">​</a></h3><p>你可以选择：</p><ul><li>本地部署</li><li>私有云部署</li><li>公有云 GPU 部署</li><li>边缘部署</li></ul><p>这对企业安全和合规很重要。</p><h3 id="优点-2-成本结构更可控" tabindex="-1">优点 2：成本结构更可控 <a class="header-anchor" href="#优点-2-成本结构更可控" aria-label="Permalink to &quot;优点 2：成本结构更可控&quot;">​</a></h3><p>闭源 API 常常是按调用付费。</p><p>开源模型部署后，成本更多来自：</p><ul><li>GPU 租赁</li><li>服务器</li><li>运维人力</li><li>存储</li><li>网络</li></ul><p>如果调用量足够大，自托管可能更划算。</p><h3 id="优点-3-可以微调" tabindex="-1">优点 3：可以微调 <a class="header-anchor" href="#优点-3-可以微调" aria-label="Permalink to &quot;优点 3：可以微调&quot;">​</a></h3><p>开源模型通常更适合做：</p><ul><li>LoRA</li><li>QLoRA</li><li>SFT</li><li>DPO</li><li>领域微调</li><li>本地量化</li></ul><p>你可以让模型更适合自己的业务。</p><h3 id="优点-4-可离线运行" tabindex="-1">优点 4：可离线运行 <a class="header-anchor" href="#优点-4-可离线运行" aria-label="Permalink to &quot;优点 4：可离线运行&quot;">​</a></h3><p>某些场景不能依赖外网，例如：</p><ul><li>工厂现场</li><li>医疗设备</li><li>政企内网</li><li>车载系统</li><li>安全审计环境</li></ul><p>开源或本地模型更适合。</p><hr><h2 id="_8-开源模型的缺点" tabindex="-1">8. 开源模型的缺点 <a class="header-anchor" href="#_8-开源模型的缺点" aria-label="Permalink to &quot;8. 开源模型的缺点&quot;">​</a></h2><h3 id="缺点-1-需要工程能力" tabindex="-1">缺点 1：需要工程能力 <a class="header-anchor" href="#缺点-1-需要工程能力" aria-label="Permalink to &quot;缺点 1：需要工程能力&quot;">​</a></h3><p>你需要懂：</p><ul><li>模型格式</li><li>GPU 显存</li><li>推理框架</li><li>量化</li><li>并发</li><li>监控</li><li>模型服务</li></ul><p>这对小团队不一定友好。</p><h3 id="缺点-2-效果不一定比闭源强" tabindex="-1">缺点 2：效果不一定比闭源强 <a class="header-anchor" href="#缺点-2-效果不一定比闭源强" aria-label="Permalink to &quot;缺点 2：效果不一定比闭源强&quot;">​</a></h3><p>开源模型进步很快，但在某些复杂任务上，闭源顶级模型仍可能更强。</p><p>尤其是：</p><ul><li>复杂推理</li><li>高质量写作</li><li>多模态理解</li><li>超长上下文</li><li>稳定工具调用</li><li>安全对齐</li></ul><h3 id="缺点-3-运维责任在你" tabindex="-1">缺点 3：运维责任在你 <a class="header-anchor" href="#缺点-3-运维责任在你" aria-label="Permalink to &quot;缺点 3：运维责任在你&quot;">​</a></h3><p>模型部署后，问题都要自己处理：</p><ul><li>服务挂了</li><li>GPU 不够</li><li>推理太慢</li><li>显存爆了</li><li>模型输出异常</li><li>版本升级后效果变差</li></ul><h3 id="缺点-4-许可证要认真看" tabindex="-1">缺点 4：许可证要认真看 <a class="header-anchor" href="#缺点-4-许可证要认真看" aria-label="Permalink to &quot;缺点 4：许可证要认真看&quot;">​</a></h3><p>不是所有开放模型都能随便商用。</p><p>有些模型对：</p><ul><li>商业使用</li><li>用户规模</li><li>再分发</li><li>训练数据</li><li>派生模型</li></ul><p>有额外限制。</p><p>产品经理和法务需要一起确认。</p><hr><h2 id="_9-开源-vs-闭源对比表" tabindex="-1">9. 开源 vs 闭源对比表 <a class="header-anchor" href="#_9-开源-vs-闭源对比表" aria-label="Permalink to &quot;9. 开源 vs 闭源对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>闭源模型</th><th>开源模型</th></tr></thead><tbody><tr><td>上手速度</td><td>快</td><td>慢一些</td></tr><tr><td>初期成本</td><td>低</td><td>可能较高</td></tr><tr><td>大规模调用成本</td><td>可能变高</td><td>可能更可控</td></tr><tr><td>数据控制</td><td>较弱，取决于服务商政策</td><td>更强，可私有化</td></tr><tr><td>模型可控性</td><td>较弱</td><td>较强</td></tr><tr><td>微调自由度</td><td>通常有限</td><td>通常更高</td></tr><tr><td>运维压力</td><td>低</td><td>高</td></tr><tr><td>能力上限</td><td>顶级闭源通常很强</td><td>取决于模型和部署能力</td></tr><tr><td>合规适配</td><td>需要评估供应商</td><td>更容易做私有化</td></tr><tr><td>适合阶段</td><td>MVP、快速验证、通用能力</td><td>成本优化、私有化、深度定制</td></tr></tbody></table><hr><h2 id="_10-产品早期怎么选" tabindex="-1">10. 产品早期怎么选？ <a class="header-anchor" href="#_10-产品早期怎么选" aria-label="Permalink to &quot;10. 产品早期怎么选？&quot;">​</a></h2><p>如果你在做 0 到 1 产品，通常建议：</p><blockquote><p>先用闭源模型快速验证价值，再根据成本、合规和可控性决定是否引入开源模型。</p></blockquote><p>因为早期最重要的是验证：</p><ul><li>用户是否真的需要这个功能</li><li>AI 是否真的能解决问题</li><li>交互流程是否成立</li><li>用户是否愿意付费</li></ul><p>如果一开始就自建模型服务，可能会把大量时间花在工程基础设施上，而不是验证产品价值。</p><hr><h2 id="_11-什么时候优先选闭源模型" tabindex="-1">11. 什么时候优先选闭源模型？ <a class="header-anchor" href="#_11-什么时候优先选闭源模型" aria-label="Permalink to &quot;11. 什么时候优先选闭源模型？&quot;">​</a></h2><p>以下情况优先考虑闭源模型：</p><h3 id="场景-1-快速做-mvp" tabindex="-1">场景 1：快速做 MVP <a class="header-anchor" href="#场景-1-快速做-mvp" aria-label="Permalink to &quot;场景 1：快速做 MVP&quot;">​</a></h3><p>你想尽快验证一个 AI 产品想法。</p><p>闭源 API 可以让你快速上线。</p><h3 id="场景-2-任务复杂-质量要求高" tabindex="-1">场景 2：任务复杂，质量要求高 <a class="header-anchor" href="#场景-2-任务复杂-质量要求高" aria-label="Permalink to &quot;场景 2：任务复杂，质量要求高&quot;">​</a></h3><p>比如：</p><ul><li>高质量写作</li><li>复杂推理</li><li>多语言客服</li><li>代码生成</li><li>多模态理解</li></ul><p>顶级闭源模型通常更省心。</p><h3 id="场景-3-团队缺少-ai-基础设施能力" tabindex="-1">场景 3：团队缺少 AI 基础设施能力 <a class="header-anchor" href="#场景-3-团队缺少-ai-基础设施能力" aria-label="Permalink to &quot;场景 3：团队缺少 AI 基础设施能力&quot;">​</a></h3><p>如果团队没有 MLE、平台工程、GPU 运维经验，闭源模型能降低门槛。</p><h3 id="场景-4-调用量还不大" tabindex="-1">场景 4：调用量还不大 <a class="header-anchor" href="#场景-4-调用量还不大" aria-label="Permalink to &quot;场景 4：调用量还不大&quot;">​</a></h3><p>早期用户量小，API 成本可能可以接受。</p><hr><h2 id="_12-什么时候优先选开源模型" tabindex="-1">12. 什么时候优先选开源模型？ <a class="header-anchor" href="#_12-什么时候优先选开源模型" aria-label="Permalink to &quot;12. 什么时候优先选开源模型？&quot;">​</a></h2><p>以下情况优先考虑开源模型：</p><h3 id="场景-1-数据不能出公司" tabindex="-1">场景 1：数据不能出公司 <a class="header-anchor" href="#场景-1-数据不能出公司" aria-label="Permalink to &quot;场景 1：数据不能出公司&quot;">​</a></h3><p>例如金融、医疗、政企、代码安全等场景。</p><h3 id="场景-2-调用量很大" tabindex="-1">场景 2：调用量很大 <a class="header-anchor" href="#场景-2-调用量很大" aria-label="Permalink to &quot;场景 2：调用量很大&quot;">​</a></h3><p>如果每天有大量请求，自托管可能更有成本优势。</p><h3 id="场景-3-需要深度微调" tabindex="-1">场景 3：需要深度微调 <a class="header-anchor" href="#场景-3-需要深度微调" aria-label="Permalink to &quot;场景 3：需要深度微调&quot;">​</a></h3><p>如果你要让模型长期稳定适配某个专业任务，开源模型更灵活。</p><h3 id="场景-4-需要本地或离线运行" tabindex="-1">场景 4：需要本地或离线运行 <a class="header-anchor" href="#场景-4-需要本地或离线运行" aria-label="Permalink to &quot;场景 4：需要本地或离线运行&quot;">​</a></h3><p>例如：</p><ul><li>本地知识库</li><li>终端设备</li><li>内网助手</li><li>工业设备</li><li>边缘 AI</li></ul><h3 id="场景-5-需要避免供应商锁定" tabindex="-1">场景 5：需要避免供应商锁定 <a class="header-anchor" href="#场景-5-需要避免供应商锁定" aria-label="Permalink to &quot;场景 5：需要避免供应商锁定&quot;">​</a></h3><p>如果你的公司希望保留模型层的自主权，开源模型更适合作为长期能力建设。</p><hr><h2 id="_13-混合策略-不要二选一" tabindex="-1">13. 混合策略：不要二选一 <a class="header-anchor" href="#_13-混合策略-不要二选一" aria-label="Permalink to &quot;13. 混合策略：不要二选一&quot;">​</a></h2><p>现实项目里，不一定非要开源或闭源二选一。</p><p>更常见的是混合架构。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>简单任务 → 小开源模型</span></span>
<span class="line"><span>复杂任务 → 闭源强模型</span></span>
<span class="line"><span>敏感数据 → 私有化模型</span></span>
<span class="line"><span>通用写作 → API 模型</span></span>
<span class="line"><span>高频 FAQ → 缓存或小模型</span></span>
<span class="line"><span>高风险决策 → AI + 人工审核</span></span></code></pre></div><p>这叫模型路由。</p><p>简单理解：</p><blockquote><p>不同任务，分配给不同模型。</p></blockquote><p>这样可以在质量、成本和安全之间取得平衡。</p><hr><h2 id="_14-什么是模型路由" tabindex="-1">14. 什么是模型路由？ <a class="header-anchor" href="#_14-什么是模型路由" aria-label="Permalink to &quot;14. 什么是模型路由？&quot;">​</a></h2><p>模型路由就是：</p><blockquote><p>系统先判断任务类型，再选择合适的模型处理。</p></blockquote><p>例如 AI 客服：</p><table tabindex="0"><thead><tr><th>用户问题</th><th>路由到哪里</th></tr></thead><tbody><tr><td>“怎么改密码？”</td><td>FAQ / 小模型</td></tr><tr><td>“我的订单为什么退款失败？”</td><td>RAG + 工具调用</td></tr><tr><td>“我要投诉并要求赔偿”</td><td>大模型 + 人工兜底</td></tr><tr><td>“总结这份合同风险”</td><td>强模型 + 引用来源</td></tr><tr><td>“查询物流状态”</td><td>工具调用，不靠模型猜</td></tr></tbody></table><p>模型路由是 AI 产品降本增效的重要方法。</p><hr><h2 id="_15-选型时看哪些指标" tabindex="-1">15. 选型时看哪些指标？ <a class="header-anchor" href="#_15-选型时看哪些指标" aria-label="Permalink to &quot;15. 选型时看哪些指标？&quot;">​</a></h2><p>选模型时，不要只看排行榜。</p><p>产品经理应该看这些维度：</p><h3 id="质量" tabindex="-1">质量 <a class="header-anchor" href="#质量" aria-label="Permalink to &quot;质量&quot;">​</a></h3><p>模型是否能完成你的真实任务？</p><h3 id="稳定性" tabindex="-1">稳定性 <a class="header-anchor" href="#稳定性" aria-label="Permalink to &quot;稳定性&quot;">​</a></h3><p>同样输入是否能稳定输出可用结果？</p><h3 id="延迟" tabindex="-1">延迟 <a class="header-anchor" href="#延迟" aria-label="Permalink to &quot;延迟&quot;">​</a></h3><p>用户等多久能拿到回答？</p><h3 id="成本" tabindex="-1">成本 <a class="header-anchor" href="#成本" aria-label="Permalink to &quot;成本&quot;">​</a></h3><p>每次请求多少钱？大规模后多少钱？</p><h3 id="上下文长度" tabindex="-1">上下文长度 <a class="header-anchor" href="#上下文长度" aria-label="Permalink to &quot;上下文长度&quot;">​</a></h3><p>能不能处理你的文档、聊天记录或代码长度？</p><h3 id="工具调用能力" tabindex="-1">工具调用能力 <a class="header-anchor" href="#工具调用能力" aria-label="Permalink to &quot;工具调用能力&quot;">​</a></h3><p>能不能稳定调用函数或外部系统？</p><h3 id="部署方式" tabindex="-1">部署方式 <a class="header-anchor" href="#部署方式" aria-label="Permalink to &quot;部署方式&quot;">​</a></h3><p>是否需要云端、私有化、本地或边缘？</p><h3 id="合规" tabindex="-1">合规 <a class="header-anchor" href="#合规" aria-label="Permalink to &quot;合规&quot;">​</a></h3><p>数据能不能发出去？日志怎么存？供应商协议是否合规？</p><h3 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h3><p>开源模型能不能商用？有没有限制？</p><hr><h2 id="_16-不要只看-benchmark" tabindex="-1">16. 不要只看 benchmark <a class="header-anchor" href="#_16-不要只看-benchmark" aria-label="Permalink to &quot;16. 不要只看 benchmark&quot;">​</a></h2><p>Benchmark 是模型评测榜单或测试集。</p><p>它有参考价值，但不能完全代表你的产品场景。</p><p>一个模型在榜单上高，不代表它一定适合你的业务。</p><p>你真正需要的是：</p><blockquote><p>用自己的真实任务做评测。</p></blockquote><p>例如你做 AI 客服，就应该准备：</p><ul><li>真实用户问题</li><li>正确答案</li><li>不同难度样本</li><li>高频问题</li><li>边界问题</li><li>投诉问题</li><li>需要查订单的问题</li></ul><p>然后比较不同模型的效果。</p><hr><h2 id="_17-一个-ai-客服选型例子" tabindex="-1">17. 一个 AI 客服选型例子 <a class="header-anchor" href="#_17-一个-ai-客服选型例子" aria-label="Permalink to &quot;17. 一个 AI 客服选型例子&quot;">​</a></h2><p>假设你要做电商 AI 客服。</p><p>需求包括：</p><ul><li>回答退款政策</li><li>查询订单状态</li><li>处理投诉</li><li>总结客服对话</li><li>生成工单</li><li>控制成本</li></ul><p>可能方案是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>退款政策 → RAG + 中等模型</span></span>
<span class="line"><span>订单状态 → 工具调用</span></span>
<span class="line"><span>简单 FAQ → 小模型或缓存</span></span>
<span class="line"><span>复杂投诉 → 强模型 + 人工审核</span></span>
<span class="line"><span>客服对话总结 → 闭源强模型或微调开源模型</span></span>
<span class="line"><span>内部质检 → 批量推理 + 低成本模型</span></span></code></pre></div><p>这比“所有问题都丢给一个最大模型”更合理。</p><hr><h2 id="_18-开源模型不等于免费" tabindex="-1">18. 开源模型不等于免费 <a class="header-anchor" href="#_18-开源模型不等于免费" aria-label="Permalink to &quot;18. 开源模型不等于免费&quot;">​</a></h2><p>这是一个常见误区。</p><p>开源模型虽然可能不用按 token 付 API 费，但你仍然要付：</p><ul><li>GPU 成本</li><li>服务器成本</li><li>运维成本</li><li>工程人力</li><li>监控系统</li><li>模型评估</li><li>安全治理</li></ul><p>所以真正要算的是：</p><blockquote><p>总拥有成本，Total Cost of Ownership，简称 TCO。</p></blockquote><p>简单说：</p><blockquote><p>不是买菜多少钱，而是开餐厅总共多少钱。</p></blockquote><hr><h2 id="_19-闭源模型不等于不可控" tabindex="-1">19. 闭源模型不等于不可控 <a class="header-anchor" href="#_19-闭源模型不等于不可控" aria-label="Permalink to &quot;19. 闭源模型不等于不可控&quot;">​</a></h2><p>闭源模型也不是完全不能用于严肃业务。</p><p>很多服务商会提供：</p><ul><li>企业版</li><li>数据不用于训练的选项</li><li>日志保留设置</li><li>私有网络连接</li><li>合规认证</li><li>访问控制</li></ul><p>但产品经理不能默认安全。</p><p>你需要和安全、法务、工程一起确认。</p><hr><h2 id="_20-本课总结" tabindex="-1">20. 本课总结 <a class="header-anchor" href="#_20-本课总结" aria-label="Permalink to &quot;20. 本课总结&quot;">​</a></h2><p>闭源模型像点外卖：快、方便、质量通常强，但可控性和长期成本需要评估。</p><p>开源模型像自建厨房：更可控、更适合私有化和深度定制，但需要工程和运维能力。</p><p>产品早期通常适合用闭源模型快速验证。</p><p>当你遇到数据合规、成本、私有化、深度微调或供应商锁定问题时，可以考虑开源模型。</p><p>现实中最常见的答案不是二选一，而是：</p><blockquote><p>混合使用，按任务路由。</p></blockquote><hr><h2 id="_21-心智模型" tabindex="-1">21. 心智模型 <a class="header-anchor" href="#_21-心智模型" aria-label="Permalink to &quot;21. 心智模型&quot;">​</a></h2><p>把闭源模型想成：</p><blockquote><p>点外卖。</p></blockquote><p>把开源模型想成：</p><blockquote><p>自建厨房。</p></blockquote><p>把模型路由想成：</p><blockquote><p>不同菜交给不同厨师做。</p></blockquote><p>简单菜交给快厨师，复杂菜交给大厨，敏感菜在自家厨房做。</p><hr><h2 id="_22-初学者常见错误" tabindex="-1">22. 初学者常见错误 <a class="header-anchor" href="#_22-初学者常见错误" aria-label="Permalink to &quot;22. 初学者常见错误&quot;">​</a></h2><h3 id="错误-1-以为开源模型就是免费" tabindex="-1">错误 1：以为开源模型就是免费 <a class="header-anchor" href="#错误-1-以为开源模型就是免费" aria-label="Permalink to &quot;错误 1：以为开源模型就是免费&quot;">​</a></h3><p>不是。</p><p>你还要付 GPU、服务器、运维和工程成本。</p><h3 id="错误-2-以为闭源模型一定不能商用" tabindex="-1">错误 2：以为闭源模型一定不能商用 <a class="header-anchor" href="#错误-2-以为闭源模型一定不能商用" aria-label="Permalink to &quot;错误 2：以为闭源模型一定不能商用&quot;">​</a></h3><p>不一定。</p><p>很多闭源模型可以商用，但要看服务条款、数据政策和合规要求。</p><h3 id="错误-3-只看模型排行榜" tabindex="-1">错误 3：只看模型排行榜 <a class="header-anchor" href="#错误-3-只看模型排行榜" aria-label="Permalink to &quot;错误 3：只看模型排行榜&quot;">​</a></h3><p>排行榜只是参考。</p><p>真实产品要用自己的数据评测。</p><h3 id="错误-4-所有任务都用同一个模型" tabindex="-1">错误 4：所有任务都用同一个模型 <a class="header-anchor" href="#错误-4-所有任务都用同一个模型" aria-label="Permalink to &quot;错误 4：所有任务都用同一个模型&quot;">​</a></h3><p>不一定。</p><p>简单任务用小模型，复杂任务用强模型，高风险任务加人工审核，通常更合理。</p><h3 id="错误-5-忽略许可证" tabindex="-1">错误 5：忽略许可证 <a class="header-anchor" href="#错误-5-忽略许可证" aria-label="Permalink to &quot;错误 5：忽略许可证&quot;">​</a></h3><p>开放权重不等于可以随便商用。</p><p>一定要看模型 license。</p><hr><h2 id="_23-小练习" tabindex="-1">23. 小练习 <a class="header-anchor" href="#_23-小练习" aria-label="Permalink to &quot;23. 小练习&quot;">​</a></h2><p>判断下面场景更适合闭源模型、开源模型，还是混合方案：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 两周内做一个 AI 写作 MVP。</span></span>
<span class="line"><span>2. 银行内部知识库，数据不能出内网。</span></span>
<span class="line"><span>3. 每天 100 万次简单客服 FAQ。</span></span>
<span class="line"><span>4. 复杂法律合同审查，要求高质量并带引用。</span></span>
<span class="line"><span>5. 手机端离线语音助手。</span></span></code></pre></div><p>参考答案：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 → 闭源模型</span></span>
<span class="line"><span>2 → 开源模型 / 私有化部署</span></span>
<span class="line"><span>3 → 开源小模型 / 缓存 / 混合方案</span></span>
<span class="line"><span>4 → 强模型 + RAG + 人工审核，可能是混合方案</span></span>
<span class="line"><span>5 → 小型开源模型 / 端侧模型</span></span></code></pre></div><hr><h2 id="_24-小项目" tabindex="-1">24. 小项目 <a class="header-anchor" href="#_24-小项目" aria-label="Permalink to &quot;24. 小项目&quot;">​</a></h2><p>为一个 AI 产品做模型选型表。</p><p>场景：AI 产品经理知识库助手。</p><table tabindex="0"><thead><tr><th>任务</th><th>推荐模型策略</th><th>原因</th></tr></thead><tbody><tr><td>总结公开文章</td><td>闭源模型</td><td>上手快，质量高</td></tr><tr><td>查询内部文档</td><td>私有 RAG + 可控模型</td><td>注意数据安全</td></tr><tr><td>高频简单问答</td><td>小模型或缓存</td><td>控制成本</td></tr><tr><td>复杂方案评审</td><td>强模型</td><td>需要更好推理和表达</td></tr><tr><td>离线演示版本</td><td>开源本地模型</td><td>不依赖网络</td></tr></tbody></table><p>练习目标：</p><blockquote><p>不要问“哪个模型最好”，而是问“哪个模型最适合这个任务”。</p></blockquote><hr><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p>第 7 课：SFT 数据集和指令微调。</p><p>我们会学习：</p><blockquote><p>如何把一个通用模型训练成更会听指令、更符合业务风格的助手？</p></blockquote>`,280)])])}const b=l(p,[["render",n]]);export{u as __pageData,b as default};
